local _, ns = ...
local Translate = ns.Lore.Translate

Translate("deDE", "deadwind-pass", {
	title = "Gebirgspass der Totenwinde",
	aliases = { "Totenwinde" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Gebirgspass der Totenwinde ist eine karge Kluft in den Bergen zwischen dem {link:duskwood}Dämmerwald{/link} und den {link:swamp-of-sorrows}Sümpfen des Elends{/link}. Ein kalter Wind heult ohne Rast hindurch, und er hat dem Pass seinen Namen gegeben. Nichts gedeiht hier recht. Die Bäume stehen grau und blattlos, das Gras ist dünn und farblos, und der Himmel darüber scheint stets die Farbe von Asche zu haben. Im Süden des Passes, in einer tiefen Senke aus zerklüftetem Boden, erhebt sich der Turm von {link:karazhan}Karazhan{/link}. Er war die Heimstatt von {link:medivh}Medivh{/link}, dem letzten {link:the-night-watch}Wächter{/link}, und der Ort, an dem er starb. Reisende, die den Pass durchqueren müssen, bleiben auf der Straße, sprechen wenig und blicken nicht zu lange zum Turm hinüber.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Keine Chronik verzeichnet, wer dem Pass zuerst seinen Namen gab oder ob er je grün war. Gewiss ist, dass er der weiteren Welt durch den Turm in seinem Herzen bekannt wurde. {link:medivh}Medivh{/link} nahm in den Jahren vor dem {link:first-war}Ersten Krieg{/link} seinen Wohnsitz in {link:karazhan}Karazhan{/link}, und von dort verfolgte er die langen Pläne, die die {link:orcs}Orcs{/link} von {red:draenor}Draenor{/red} nach {link:azeroth}Azeroth{/link} brachten. Der Pass lag am südöstlichen Rand des alten Königreichs {link:kingdom-of-stormwind}Azeroth{/link}, und nur wenige Bewohner des Königreichs hatten Grund, dorthin zu gehen. Der {link:the-night-watch}Wächter{/link} war ein Freund des Königs, und sein Turm wurde in Frieden gelassen.]=],
		},
		{
			title = "Die Gegenwart",
			text = [=[{link:medivh}Medivh{/link} ist lange tot, und sein Turm steht dunkel und verschlossen. Der Pass gehört heute keinem Königreich. {link:kingdom-of-stormwind}Stormwind{/link} schickt keine Patrouillen so weit nach Osten, und auch die {link:horde}Horde{/link} unterhält hier keinen Posten. Ruhelose Geister treiben zwischen den Ruinen am Fuß von {link:karazhan}Karazhan{/link} umher, und bleiche, unlebendige Wesen pflegen die Gräber von {link:morgan-s-plot}Morgans Plot{/link} dahinter. {link:ogres}Oger{/link} haben ihre Hügel an der südlichen Straße errichtet, in einem engen Tal namens {link:the-vice}Das Laster{/link}. Große Aasvögel kreisen über den Schluchten. Auf der Straße selbst eilen Händler und Soldaten auf dem Weg zu den Sümpfen des Elends und den {link:blasted-lands}Verwüsteten Landen{/link} bei Tageslicht hindurch. Im {link:duskwood}Dämmerwald{/link} erzählen die Leute von {link:darkshire}Dunkelhain{/link}, dass die {link:dark-riders}dunklen Reiter{/link}, die die Familie Yorgen niedermetzelten, aus diesem Pass herabkamen, und dass niemand weiß, wohin sie gehen, wenn sie zurückkehren.]=],
		},
		{
			title = "Bewohner",
			text = [=[• {b}Die ruhelosen Toten.{/b} Schatten, klagende Gespenster und verdammte Seelen spuken in den verfallenen Häusern vor {link:karazhan}Karazhan{/link}. Wessen Geister sie sind, kann kein lebender Zeuge sagen.
• {b}Die Unlebendigen von {link:morgan-s-plot}Morgans Plot{/link}.{/b} Bleiche Hüter und Bewohner halten die Kapelle und den Friedhof hinter dem Turm.
• {b}Die Oger der Totenwinde.{/b} Die {link:deadwind-ogres}Oger der Totenwinde{/link} halten {link:razorfen-downs}die Hügel{/link} des Lasters und das {link:grosh-gok-compound}Grosh'gok{/link} Lager, und unter ihnen sind Hexenmeister und Ogermagier.
• {b}Aasvögel.{/b} Geier, die man Himmelsschatten nennt, kreisen über den nördlichen Schluchten und dem offenen Gelände des Passes.
• {b}Die dunklen Reiter.{/b} Bei Tag sieht man sie hier nicht. Doch die Überlebenden des Dämmerwalds nennen den Pass der Totenwinde als den Ort, aus dem sie reiten.]=],
		},
		{
			title = "Geschichte",
			text = [=[• {b}Der Turm des Wächters.{/b} {link:medivh}Medivh{/link} nahm seinen Wohnsitz in {link:karazhan}Karazhan{/link}, nachdem er aus dem langen Schlaf seiner Jugend erwacht war. Dort studierte er, trug eine große Bibliothek zusammen und empfing nur wenige Gäste.
• {b}Die Öffnung des Portals.{/b} Vom Turm aus griff Medivh über die Leere hinweg nach Draenor und nach dem Hexenmeister {link:gul-dan}Gul'dan{/link}. Gemeinsam öffneten sie das {link:dark-portal}Dunkle Portal{/link} im Schwarzen Fenn, weit im Süden.
• {b}Der Lehrling und die Gesandte.{/b} Die {link:kirin-tor}Kirin Tor{/link} von {link:dalaran}Dalaran{/link} schickten den jungen Magier {link:khadgar}Khadgar{/link}, um Medivh als Lehrling zu dienen. Die Halborcin {link:garona}Garona{/link} kam als Gesandte der {link:horde}Horde{/link} zum Turm. Gemeinsam erfuhren sie die Wahrheit über den Verrat des Wächters.
• {b}Der Tod des Wächters.{/b} Sir {link:anduin-lothar}Anduin Lothar{/link} und Khadgar erklommen Karazhan und stellten sich Medivh. Dort wurde der {link:the-night-watch}Wächter{/link} erschlagen. Gul'dan, der in diesem Augenblick in Medivhs Geist gegriffen hatte, fiel in eine lange Starre.
• {b}Die Stille.{/b} Seit jenem Tag ist der Turm dunkel. Der Erste Krieg und der {link:second-war}Zweite Krieg{/link} gingen an ihm vorüber, und der Pass um ihn herum ist zu einem Ort geworden, den die Lebenden meiden.]=],
		},
		{
			title = "Überlieferungen des Passes",
			text = [=[• Die Straße, die vom {link:duskwood}Dämmerwald{/link} zu den Sümpfen des Elends führt, ist der einzige sichere Weg hindurch. Alte Warnschilder stehen an ihrem Rand, und auf einem steht schlicht: „Kehrt um!“
• Neben der Wegkreuzung steht ein toter Baum, und an seinen Ästen baumeln noch die Gehenkten. Niemand im Dämmerwald behauptet zu wissen, wer sie gehängt hat.
• Die {link:ogres}Oger{/link} des Lasters halten in ihren {link:camping}Lagern{/link} Feuer und große Kessel am Brennen. Was sie in einem so toten Land zu finden hoffen, hat sie niemand gefragt.
• Hinter dem Turm liegen eine kleine Kapelle und ein Friedhof. Welche Gemeinde sich dort einst auch versammelte, ihre Toten ruhen nicht.]=],
		},
		{
			title = "Unverzeichnet",
			text = [=[Keine Chronik erzählt, warum das Land des Passes so karg ist oder ob es schon so war, bevor {link:medivh}Medivh{/link} kam. Auch berichtet keine Überlieferung, wer in den verfallenen Häusern unterhalb von {link:karazhan}Karazhan{/link} lebte oder was aus ihnen wurde. Dieser Eintrag hält fest, was Reisende sehen und was die Geschichten des Wächters bezeugen.]=],
		},
	},
	mentions = {
		{
			text = [=[Svens Rache, wo die dunklen Reiter der Totenwinde zuerst genannt werden]=],
		},
	},
})

Translate("deDE", "karazhan", {
	title = "Karazhan",
	aliases = { "Medivhs Turm", "der Turm von Karazhan" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Karazhan ist der Turm von {link:medivh}Medivh{/link}, dem letzten {link:the-night-watch}Wächter{/link}. Er erhebt sich aus einer tiefen Senke im Süden des {link:deadwind-pass}Gebirgspasses der Totenwinde{/link}, eine hohe Spitze aus dunklem Stein über verstreuten, verfallenen Häusern. Jahrelang war er der Sitz eines der mächtigsten Magier, die die Welt je gekannt hat. Er ist auch der Ort, von dem aus der {link:first-war}Erste Krieg{/link} in Gang gesetzt wurde, und der Ort, an dem sein Urheber starb. Seine Tore sind nun geschlossen. Kein Diener antwortet an seinem Tor, und kein Licht wird für Gäste entzündet.]=],
		},
		{
			title = "Das Haus des Wächters",
			text = [=[{link:medivh}Medivh{/link} kam als erwachsener Mann nach Karazhan, nach dem langen Schlaf seiner Jugend in der {link:northshire-abbey}Abtei von Nordhain{/link}. Er lebte dort nur mit einem kleinen Haushalt von Dienern, angeführt von einem betagten Kastellan. Der Turm barg eine große Bibliothek, Räume voller seltsamer Instrumente und eine Sternwarte, die zu den Sternen hin offen war. Wer in seinen Mauern weilte, merkte, dass er sich nicht immer an die Gegenwart hielt. {link:khadgar}Khadgar{/link} sah in seiner Zeit als Lehrling in den Hallen Szenen aufsteigen und verblassen, die zu anderen Tagen gehörten, manche lange vergangen und manche, die noch nicht gekommen waren. Die Magier der {link:kirin-tor}Kirin Tor{/link} hatten lange gewünscht, die Geheimnisse des Turms zu ergründen. Keiner von ihnen wurde je eingelassen, bis der {link:the-night-watch}Wächter{/link} schließlich einwilligte, einen Lehrling aufzunehmen.]=],
		},
		{
			title = "Der Verrat",
			text = [=[Innerhalb dieser Mauern griff {link:medivh}Medivh{/link} über die Leere hinweg nach der sterbenden Welt {red:draenor}Draenor{/red}. Er fand den Hexenmeister {link:gul-dan}Gul'dan{/link} und die {link:orcs}Orcs{/link}, die ihm dienten, und gemeinsam öffneten sie das {link:dark-portal}Dunkle Portal{/link}. Jahrelang wussten die Freunde des Wächters in {link:stormwind-city}Stormwind{/link} nichts davon. Die Wahrheit kam durch zwei unwahrscheinliche Verbündete aus dem Turm: {link:khadgar}Khadgar{/link}, den Lehrling, den {link:dalaran}Dalaran{/link} geschickt hatte, und {link:garona}Garona{/link}, die Halborc-Gesandte der {link:horde}Horde{/link}. Was sie in Karazhan erfuhren, trugen sie zu König {link:llane-wrynn}Llane Wrynn{/link}.]=],
		},
		{
			title = "Die letzte Schlacht",
			text = [=[Sir {link:anduin-lothar}Anduin Lothar{/link} und {link:khadgar}Khadgar{/link} kehrten nach Karazhan zurück, um den Krieg an seiner Wurzel zu beenden, und {link:garona}Garona{/link} stand ihnen bei. Sie kämpften gegen den {link:the-night-watch}Wächter{/link} in seinem eigenen Turm, und {link:medivh}Medivh{/link} wurde erschlagen. Im selben Augenblick durchsuchte {link:gul-dan}Gul'dan{/link} den Geist des Wächters nach den Geheimnissen des Grabmals des {link:sargeras}Sargeras{/link}. Als Medivh starb, wurde der Hexenmeister in eine Starre geworfen, aus der er lange nicht erwachte. Khadgar stieg vom Turm herab, weit über seine Jahre hinaus gealtert. Karazhan blieb leer hinter ihm zurück.]=],
		},
		{
			title = "In diesen Tagen",
			text = [=[Der Turm ist versiegelt. Die Geister, die zwischen den verfallenen Häusern zu seinen Füßen umhertreiben, sind seine einzige Gesellschaft. Doch Medivhs Wissen ist nicht ganz verschwunden. Die Abhandlungen Khadgars, des letzten Lehrlings des Turms, werden von den Gelehrten von {link:stormwind-city}Stormwind{/link} noch immer abgeschrieben und studiert, und die {link:the-night-watch}Wächter{/link}, die von {link:nethergarde-keep}Burg Nethergarde{/link} aus das Dunkle Portal bewachen, suchen nach ihnen.]=],
		},
		{
			title = "Unverzeichnet",
			text = [=[Keine Chronik erzählt, wer Karazhan errichtete, wann es erbaut wurde oder warum es an einem so trostlosen Ort steht. Was in diesen Tagen hinter seinen versiegelten Toren liegt, hat kein lebender Zeuge niedergeschrieben.]=],
		},
	},
	chapters = {
		{
			title = "Die Abhandlungen des Lehrlings",
			hint = [=[Bringt die verlorene Abhandlung eines Gelehrten zurück und überbringt sie den Wächtern, die das Dunkle Portal bewachen.]=],
			text = [=[Ein Bote der Akademie von {link:stormwind-city}Stormwind{/link} brach mit einem kostbaren Text nach {link:nethergarde-keep}Nethergarde{/link} auf: Khadgars Abhandlungen über das Zusammentreffen der Welten. In den Sümpfen des Elends verlor er ihn an Kreaturen des Moors. Als der Text schließlich die Burg erreichte, konnte der {link:the-night-watch}Wächter{/link}, der ihn angefordert hatte, kaum erwarten, damit zu beginnen. Der Mann, der einst an Medivhs Seite studiert hatte, hatte besser als irgendein Lebender verstanden, wie zwei Welten miteinander verbunden worden waren. Jene, die nun über das Portal wachen, wollten es ebenfalls verstehen.]=],
		},
	},
	mentions = {
		{ text = "Mazens Auftrag, der Hilferuf aus der Bibliothek der Akademie" },
		{
			text = [=[Mazens Auftrag, Khadgars Abhandlungen nach {link:nethergarde-keep}Burg Nethergarde{/link} gebracht]=],
		},
	},
	bonds = {
		{ id = "medivh", name = "Medivh", note = "sein Herr" },
		{ id = "khadgar", name = "Khadgar", note = "sein letzter Lehrling" },
		{ id = "garona", name = "Garona", note = "kam als Gesandte der Horde" },
		{ id = "anduin-lothar", name = "Anduin Lothar", note = "erschlug hier den Wächter" },
		{ id = "aegwynn", name = "Aegwynn", note = "die Mutter des Wächters" },
	},
})

Translate("deDE", "morgan-s-plot", {
	title = "Morgans Plot",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Morgans Plot ist eine kleine Kapelle mit Friedhof, die gleich hinter {link:karazhan}Karazhan{/link} liegen. Ihre Steine neigen sich, und ihr Dach ist zur Hälfte verschwunden. Vielleicht diente sie einst dem Dorf, das zu Füßen des Turms stand, doch niemand erinnert sich heute, wer dort begraben wurde oder wer der {link:morgan-stern}Morgan{/link} ihres Namens gewesen sein mag. Die Gräber bleiben nicht unbehelligt. Bleiche Gestalten, die unlebendigen Hüter und Bewohner des Ortes, wandeln zwischen der Kapelle und dem Hang, als hätten sie noch Pflichten zu erfüllen. Besucher heißen sie nicht willkommen.]=],
		},
	},
})

Translate("deDE", "deadman-s-crossing", {
	title = "Totmannsfurt",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Totmannsfurt ist der Ort, an dem sich die Straße durch den {link:deadwind-pass}Gebirgspass der Totenwinde{/link} teilt. Ein Weg führt nach Westen in den {link:duskwood}Dämmerwald{/link}, einer nach Osten zu den {link:swamp-of-sorrows}Sümpfen des Elends{/link} und einer nach Süden, hinab in die Senke von {link:karazhan}Karazhan{/link}. An der Kreuzung steht ein toter Baum, und von seinen Ästen hängen die Leiber der Gehenkten. Ein Wegweiser erteilt Reisenden den unverblümten Rat umzukehren. Die meisten befolgen ihn auf ihre Weise: Sie bleiben auf der Straße und nehmen nicht die Abzweigung nach Süden.]=],
		},
	},
})

Translate("deDE", "ariden-s-camp", {
	title = "Aridens Lager",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Aridens Lager ist ein verlassener Lagerplatz gleich nördlich der Straße, die durch den {link:deadwind-pass}Gebirgspass der Totenwinde{/link} führt. Eine kalte Feuerstelle und ein paar zurückgelassene Habseligkeiten sind alles, was bleibt. Wer auch immer Ariden war, verließ das Lager in Eile, oder verließ es gar nicht. Nur wenige Reisende halten hier an. In einem Land, in dem die Toten wandeln und {link:ogres}Oger{/link} die Straße beobachten, ist ein einsames Feuer eine Einladung, die kaum jemand auszusprechen wagt.]=],
		},
		{
			title = "Unverzeichnet",
			text = [=[Keine Chronik dieser Tage verzeichnet, wer Ariden war, was ihn in den Pass der {link:deadwind-pass}Totenwinde{/link} führte oder was aus ihm wurde.]=],
		},
	},
})

Translate("deDE", "the-vice", {
	title = "Das Laster",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Laster ist ein enges Tal im Südosten des {link:deadwind-pass}Gebirgspasses der Totenwinde{/link}, wo steile Felswände die Straße nach {link:karazhan}Karazhan{/link} einschließen. Die {link:deadwind-ogres}Oger der Totenwinde{/link} haben ihre Hügel in diese Wände gegraben. Aus ihren Höhlen beobachten sie die Straße unter ihnen, und ihre Feuer und Kessel qualmen zwischen den Steinen. Rohlinge und Zerfleischer bewachen die Lager, während Hexenmeister und Ogermagier bei den Feuern bleiben. Niemand weiß, warum die {link:ogres}Oger{/link} einen so toten Ort als Heimat gewählt haben.]=],
		},
	},
})

Translate("deDE", "grosh-gok-compound", {
	title = "Das Grosh'gok Lager",
	aliases = { "Grosh'gok" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Grosh'gok Lager ist der größte der Ogerhügel des Lasters und der südlichste. Seine Höhlen reichen tief in die Klippen über der Straße nach {link:karazhan}Karazhan{/link}. Es ist der Hauptbau der {link:deadwind-ogres}Oger der Totenwinde{/link}, und die Hexenmeister des Klans halten sich in seiner Nähe. Reisende, die nahe dem Lager von der Straße abkommen, haben selten Gelegenheit, noch einmal abzukommen.]=],
		},
	},
})

Translate("deDE", "sleeping-gorge", {
	title = "Die schlummernde Schlucht",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die schlummernde Schlucht ist ein kleiner Abgrund im Osten des {link:deadwind-pass}Gebirgspasses der Totenwinde{/link}. Einer der Pfade, die nach Süden zu {link:karazhan}Karazhan{/link} führen, verläuft ein Stück auf ihrem Grund und biegt dann nach Osten ins Laster ab. Wer auch immer sie benannte, die Schlucht ist kein Ort der Ruhe. Reisende, die sie durchqueren, gehen leise, denn gleich dahinter liegen die {link:ogres}Oger{/link} des Lasters.]=],
		},
	},
})

Translate("deDE", "deadwind-ravine", {
	title = "Schlucht der Totenwinde",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Schlucht der Totenwinde ist der breite Einschnitt, durch den die Straße aus dem {link:duskwood}Dämmerwald{/link} hinauf in den {link:deadwind-pass}Gebirgspass der Totenwinde{/link} steigt. Hier weichen die dunklen Wälder endlich grauem Stein und toten Bäumen. Der Wind, der dem Pass seinen Namen gibt, weht in der Schlucht am stärksten, und große Aasvögel, die man Himmelsschatten nennt, reiten über ihr auf ihm und halten nach allem Ausschau, was fällt. Für jene, die aus {link:darkshire}Dunkelhain{/link} kommen, ist die Schlucht der erste Blick auf ein Land, das noch trostloser ist als ihr eigenes.]=],
		},
	},
})

Translate("deDE", "deadwind-ogres", {
	title = "Oger der Totenwinde",
	aliases = { "Totenwind-Oger", "Oger des Passes der Totenwinde" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Oger der Totenwinde sind die {link:ogres}Oger{/link}, die sich im Süden des {link:deadwind-pass}Gebirgspasses der Totenwinde{/link} niedergelassen haben. Sie hausen in Hügeln, die in die Klippen des Lasters gegraben sind, und der größte davon ist das {link:grosh-gok-compound}Grosh'gok{/link} Lager. Keine Chronik verzeichnet, woher sie kamen, wann, oder was sie in ein Land zog, in dem fast nichts lebt.]=],
		},
		{
			title = "Ihre Lebensweise",
			text = [=[Der Klan hat Rohlinge und Zerfleischer, die seine Lager und die Straße darunter bewachen. Er hat auch Hexenmeister und Ogermagier, die die Feuer und Kessel der Hügel hüten. Dass der Klan Hexenmeister zu seinen Mitgliedern zählt, ist ein finsteres Zeichen. Die dunklen Künste kamen mit der {link:horde}Horde{/link} zu den Ogern von {link:azeroth}Azeroth{/link}, und niemand weiß, von wem diese {link:ogres}Oger{/link} sie gelernt haben.]=],
		},
		{
			title = "In der Gegenwart",
			text = [=[Die {link:ogres}Oger{/link} überfallen jeden, der von der Straße in Richtung {link:karazhan}Karazhan{/link} abkommt. Den Turm selbst behelligen sie, soweit man weiß, nicht, und der Turm behelligt sie nicht. Kein Königreich hat Soldaten gegen sie geschickt. Der Pass der {link:deadwind-pass}Totenwinde{/link} liegt zu weit von jedem Herrn entfernt, den es kümmern könnte.]=],
		},
		{
			title = "Unverzeichnet",
			text = [=[Warum die {link:ogres}Oger{/link} das Laster wählten und was sie mit einem so toten Land wollen, steht nirgendwo geschrieben. Auch der Name ihres Anführers nicht.]=],
		},
	},
})

Translate("deDE", "dark-riders", {
	title = "Dunkle Reiter",
	aliases = { "dunkle Reiter", "Dunkler Reiter" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die dunklen Reiter sind eine Schar von Berittenen, die aus dem {link:deadwind-pass}Gebirgspass der Totenwinde{/link} kommen, um den Süden des {link:duskwood}Dämmerwalds{/link} heimzusuchen. Sie reiten in Schwarz und schlagen ohne Warnung zu. Viel mehr ist über sie nicht bekannt. Sie führen kein bekanntes Banner, sie sprechen mit niemandem, der sie überlebt, und sie kehren in den Pass zurück, wenn ihr Werk getan ist.]=],
		},
		{
			title = "Ihre Taten",
			text = [=[Es waren die dunklen Reiter, die über den Hof von {link:sven-yorgen}Sven Yorgen{/link} herfielen, während er fort war, und seine Familie töteten. Sven verfolgte sie und verlor ihre Spur. Ein Bergmann, der aus der Mine bei {link:roland-s-doom}Rolands Verdammnis{/link} geflohen war, versteckte sich in jener Nacht in der Scheune der Yorgens und sah das Gemetzel. Sein Tagebuch erzählte Sven später den Rest. Man weiß, dass die Reiter den Totenbeschwörer {link:morbent-fel}Morbent Fel{/link} im {link:forlorn-rowe}Verlassenen Gut{/link} oberhalb von {link:raven-hill}Rabenflucht{/link} aufsuchen. Sven hat sie dort mit ihm sprechen sehen.]=],
		},
		{
			title = "In der Gegenwart",
			text = [=[{link:morbent-fel}Morbent Fel{/link} mag fallen, doch die Reiter bleiben frei. {link:sven-yorgen}Sven Yorgen{/link} hält sein Lager am Westrand des Dämmerwalds und lebt für den Tag, an dem er sie finden kann. Was auch immer sie suchen und wem auch immer sie dienen, sie wurden noch nicht zur Rechenschaft gezogen.]=],
